body.script:
//
					const cfg   = document.getElementById('cfg').dataset;
					const ASSET = cfg.asset;
					// Server-rendered `?as_of=` from the page's own URL (see
					// time_machine_chart's own docstring) — pre-fills the "As
					// Of" input so a specific historical view is bookmarkable.
					// Interpreted as EUROPE/BERLIN wall-clock time (the picker's
					// own zone — see setAsOfInput()/berlinNaiveToUtcIso()
					// below), same as a value the user types; it is converted
					// to UTC client-side before any backend call. Empty string
					// (not set) means "start at now", same as a bare
					// /tm/<asset> visit.
					const INITIAL_AS_OF = cfg.asOf || '';
					// Coinbase spot, same symbol convention /4l/<asset> uses
					// (server-side _COINBASE_SYMBOL_MAP).
					const COINBASE_SYMBOL = { BTC: 'BTC-USD', ETH: 'ETH-USD' }[ASSET] || (ASSET + '-USD');
					document.getElementById('exchange-label').textContent = 'Coinbase · ' + COINBASE_SYMBOL;

					// "As Of" — the single moment this whole page is frozen at.
					// The <input type="datetime-local"> and the URL's own
					// `?as_of=` are both EUROPE/BERLIN wall-clock time (DST-
					// aware — the picker's label says "As Of (Berlin)"), per
					// product decision, since this Thales tool's users think in
					// Berlin time. AS_OF_ISO, by contrast, is always the
					// equivalent naive-UTC "YYYY-MM-DDTHH:MM:SS" (converted from
					// the Berlin input by berlinNaiveToUtcIso() in
					// setAsOfInput(); seconds forced to :00 so the server's
					// _parse_as_of_param (main.py) always gets a fully-formed
					// ISO string regardless of Python's own fromisoformat
					// version quirks around omitted seconds). Every fetch on
					// this page appends `&as_of=` + AS_OF_ISO (so the backend
					// always receives UTC, matching this addon's UTC-anchored
					// trade-window convention), and the Window vertical line
					// below is measured back from it too (asOfEpochSeconds()),
					// not from real "now".
					let AS_OF_ISO = null;

					function pad(n) { return String(n).padStart(2, '0'); }

					// Formats a JS Date as a naive-UTC "YYYY-MM-DDTHH:MM"
					// string (UTC getters, not local) — used only as the tail
					// end of berlinNaiveToUtcIso() below.
					function toDatetimeLocalUTC(date) {
						return date.getUTCFullYear() + '-' + pad(date.getUTCMonth() + 1) + '-' + pad(date.getUTCDate())
							+ 'T' + pad(date.getUTCHours()) + ':' + pad(date.getUTCMinutes());
					}

					// Formats a JS Date as the Europe/Berlin wall-clock
					// "YYYY-MM-DDTHH:00" string the <input type="datetime-
					// local"> shows — DST-aware via Intl ('sv-SE' renders an
					// ISO-like "YYYY-MM-DD HH:MM:SS"; the space becomes 'T').
					// Minutes are ALWAYS truncated to :00 (per product
					// decision — the picker only ever operates at hour
					// granularity, matching the Window dropdown's own
					// whole-hour steps and the hour-granular trade filtering
					// downstream). Used for the "Now" button and, via
					// defaultAsOfBerlinNaive(), the page's own default.
					function toDatetimeLocalBerlin(date) {
						return date.toLocaleString('sv-SE', { timeZone: 'Europe/Berlin' }).replace(' ', 'T').slice(0, 13) + ':00';
					}

					// Europe/Berlin's UTC offset in seconds (Berlin - UTC,
					// positive) at `refDate`, DST-aware (CET/CEST) via Intl's
					// own timezone data rather than a fixed UTC+1/+2 guess —
					// same "diff two toLocaleString renderings of the same
					// instant" idiom the page-wide `tzOffset` above uses, just
					// for Berlin instead of the viewer's own browser zone.
					function berlinOffsetSeconds(refDate) {
						const utc = new Date(refDate.toLocaleString('en-US', { timeZone: 'UTC' }));
						const berlin = new Date(refDate.toLocaleString('en-US', { timeZone: 'Europe/Berlin' }));
						return (berlin - utc) / 1000;
					}

					// Converts a Berlin wall-clock "YYYY-MM-DDTHH:MM[:SS]"
					// string (what the picker / URL `?as_of=` carry) to the
					// equivalent naive-UTC "YYYY-MM-DDTHH:MM:SS" string
					// (AS_OF_ISO — what every backend call and asOfEpochSeconds()
					// expect). DST-aware: the offset is resolved for the TARGET
					// date itself (CET vs CEST), not "now", by building a
					// first-guess UTC instant from the wall-clock components and
					// reading Berlin's offset at that instant. The ~1h
					// ambiguity right at a DST transition (a nonexistent
					// spring-forward hour, a doubled fall-back hour) is inherent
					// to any naive-local→instant conversion and immaterial for a
					// historical-inspection tool.
					function berlinNaiveToUtcIso(berlinNaive) {
						const [datePart, timePart] = berlinNaive.slice(0, 16).split('T');
						const [y, m, d] = datePart.split('-').map(Number);
						const [H, M] = timePart.split(':').map(Number);
						const guessUTC = Date.UTC(y, m - 1, d, H, M, 0);
						const offsetSec = berlinOffsetSeconds(new Date(guessUTC));
						return toDatetimeLocalUTC(new Date(guessUTC - offsetSec * 1000)) + ':00';
					}

					// The page's own default "As Of" when no `?as_of=` was
					// given on the URL — the current Europe/Berlin date and
					// hour, minutes truncated to :00 (e.g. 11:37 Berlin →
					// "…T11:00"), per product decision. Just
					// toDatetimeLocalBerlin(now), which already zeroes the
					// minutes and resolves Berlin's own wall clock (DST-aware,
					// and Berlin's own calendar day near midnight) for us.
					function defaultAsOfBerlinNaive() {
						return toDatetimeLocalBerlin(new Date());
					}

					function setAsOfInput(value) {
						// `value` is a Berlin wall-clock string — a typed value,
						// the "Now" button's toDatetimeLocalBerlin(), or a
						// server-rendered URL `?as_of=` (not guaranteed to match
						// the plain "YYYY-MM-DDTHH:MM" shape the <input>'s own
						// .value getter produces, so sliced to 16 chars first).
						const berlin = value.slice(0, 16);
						document.getElementById('as-of-input').value = berlin;
						// AS_OF_ISO is the equivalent naive-UTC instant — this is
						// the single Berlin→UTC conversion point on the page.
						AS_OF_ISO = berlinNaiveToUtcIso(berlin);
					}

					// AS_OF_ISO is a naive-UTC string (berlinNaiveToUtcIso()'s
					// output), so a bare `new Date(AS_OF_ISO)` would parse it as
					// browser-LOCAL time in most engines — appending 'Z' forces
					// UTC parsing instead. Returns null if AS_OF_ISO isn't set
					// yet (before setAsOfInput()'s first call), so callers can
					// treat that as "nothing to position against" rather than
					// NaN.
					function asOfEpochSeconds() {
						if (!AS_OF_ISO) return null;
						return Math.floor(Date.parse(AS_OF_ISO + 'Z') / 1000);
					}

					// "Timeframe" dropdown — same options as /4l/<asset>'s own,
					// defaulting to 1h here (was 4h — this page's own
					// pre-rebuild default — changed per product decision, kept
					// at 1h through the move back onto /4l, whose own default
					// is 4h). See
					// TF_WINDOW below for the per-timeframe visible-window
					// convention this page shares with /4l.
					let INTERVAL = '1h';
					const klineUrl = (iv, limit) =>
						'/api/klines-coinbase/' + ASSET + '?interval=' + iv + '&limit=' + limit + '&as_of=' + encodeURIComponent(AS_OF_ISO);

					// "Expiry" dropdown — which expiry's trades feed the 4
					// gamma legs. Dynamically loaded from every instrument that
					// had already traded and hadn't yet expired AS OF AS_OF_ISO
					// (loadExpiries(), sourced from /api/expiries/<asset>
					// ?as_of=<AS_OF_ISO> — dankbit.bands._distinct_expirations_asof()),
					// soonest-first, reloaded whenever the As-Of moment changes.
					// Each option ISOLATES trades to that one instrument's own
					// trades via four_leg_gamma_json's own ?instrument= override.
					// (A "Cumulative" checkbox — ?cumulative=1, span every
					// instrument expiring on or before the selected one — was
					// removed per product decision, along with /4l/<asset>'s
					// own; the route mode itself is unchanged, still reachable
					// by a direct API call.)
					let SELECTED_INSTRUMENT = null;
					// "Window" dropdown — trailing-hours trade window ending at
					// AS_OF_ISO (not "now"), fed into the selected expiry's
					// trades. Mirrors /4l/<asset>'s own option set
					// (1h/2h/3h/4h/8h/24h/48h/72h/All, 4h default — synced with
					// /4l's own set and default per product decision
					// (2026-09-23, again 2026-09-29 when both moved to 4h).
					// 'all' skips the trailing-hours filter entirely; a number
					// otherwise. (A "00:00 UTC" and an "Auto (Time to Expiry)"
					// option were both offered here at various points — the
					// server-side ?hours=midnight/?hours=auto resolutions are
					// unchanged and still reachable by a direct API call, just
					// no longer in this dropdown.)
					let WINDOW_HOURS = 4;
					// If ?hours=auto is ever driven in (not from this dropdown
					// any more), this holds the numeric hours the server
					// resolved it to; null otherwise.
					let autoResolvedHours = null;
					const fourLegGammaUrl = () =>
						'/api/four-leg-gamma/' + ASSET + '?instrument=' + SELECTED_INSTRUMENT + '&hours=' + WINDOW_HOURS
						+ '&as_of=' + encodeURIComponent(AS_OF_ISO);

					// Trade count for the currently selected Window/Expiry —
					// same `trade_count` field /api/four-leg-gamma returns.
					// null until the first refreshFourLegGamma() resolves.
					let tradeCount = null;

					// Same browser-local-timezone shift every other TV chart page
					// in this addon applies — Lightweight Charts always renders
					// epoch seconds as UTC wall-clock time, so every timestamp fed
					// into the chart is pre-shifted by the viewer's own current
					// UTC offset first.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }

					// "Settings" button/dialog — user-pickable colors for this
					// page's own 4 gamma-leg lines plus the Dominant Leg, Δ0
					// and γ flip lines, persisted per-browser under a key
					// completely independent of /4l/<asset>'s own
					// 'dankbit_4l_chart_colors' and every other page's own
					// color settings, since Time Machine is its own page. No
					// line-style picker (the 4 gamma legs and Dominant Leg are
					// solid, Δ0/γ flip dotted — never user-restylable).
					// Defaults match /4l's own (LC/LP black, SC/SP orange,
					// Dominant Leg violet, Δ0 green, γ flip violet).
					const COLOR_STORAGE_KEY = 'dankbit_tm_chart_colors';
					const DEFAULT_COLORS = {
						bcg: '#000000', bpg: '#000000', scg: '#fb8c00', spg: '#fb8c00', dominant: '#8e24aa', deltazero: '#2e7d32', gammaflip: '#7e57c2', gammapeak: '#d81b60',
					};
					let chartColors = Object.assign({}, DEFAULT_COLORS);
					try {
						const savedColors = JSON.parse(localStorage.getItem(COLOR_STORAGE_KEY) || '{}');
						Object.keys(DEFAULT_COLORS).forEach(key => {
							if (savedColors[key]) chartColors[key] = savedColors[key];
						});
					} catch (e) { /* malformed stored value — fall back to defaults */ }

					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					// Watermark — this page only (not /4l/<asset> or the Delta
					// Chart), via Lightweight Charts v4's own built-in
					// `watermark` chart option (drawn directly onto the chart's
					// own canvas, so it's properly clipped/resized along with
					// everything else — not a hand-rolled DOM overlay). Fixed
					// gray, deliberately NOT theme-reactive (unlike every other
					// themed chart option on this page) — a light/dark-switching
					// black-ish/white-ish color went invisible in practice
					// (white-on-white in Light, black-on-black in Dark), so a
					// single mid-gray at moderate alpha is used instead, which
					// reads against both a white and a black background without
					// needing to track DARK_MODE at all.
					const WATERMARK_TEXT = 'Dankbit Time Machine';
					const WATERMARK_COLOR = 'rgba(120,120,120,0.35)';

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						watermark: { visible: true, text: WATERMARK_TEXT, fontSize: 36, color: WATERMARK_COLOR, horzAlign: 'center', vertAlign: 'center' },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
						updateWindowVLine();
					});
					chart.timeScale().subscribeVisibleLogicalRangeChange(() => updateWindowVLine());
					// #tf-bar wraps onto extra rows on a narrow viewport (see its
					// own CSS comment) — #exchange-label/#ruler-info (stacked
					// underneath it) track its actual measured bottom edge via
					// this custom property instead of a hardcoded offset, so a
					// taller (wrapped) toolbar can never overlap them.
					function repositionBelowToolbar() {
						const bar = document.getElementById('tf-bar');
						if (!bar) return;
						const bottom = Math.ceil(bar.getBoundingClientRect().bottom);
						document.documentElement.style.setProperty('--tf-bar-bottom', bottom + 'px');
					}
					window.addEventListener('resize', repositionBelowToolbar);
					repositionBelowToolbar();

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// Invisible helper series solely to extend the shared time
					// axis a little past the last historical candle, same
					// mechanism /4l/<asset>'s own futureAxisSeries uses — just
					// breathing room for the 4 gamma price lines' own axis
					// labels, not a claim about real future price action (this
					// page shows a frozen past moment, not a live forecast).
					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					// The 4 gamma "lines" are horizontal reference lines at the
					// resolved As-Of/Window reading — same createPriceLine()
					// pattern /4l/<asset> uses — redrawn fresh whenever As
					// Of/Timeframe/Expiry/Window changes.
					let bcgPriceLine = null, bpgPriceLine = null, scgPriceLine = null, spgPriceLine = null;
					// Dominant Leg line — at the price of whichever present leg
					// (price != 0) has the largest |gamma value| for this
					// Expiry/Window/As-Of. Same as /4l/<asset>'s own.
					let dominantLegPriceLine = null;
					// Delta = 0 lines (green, dotted) — one per entry in the
					// response's own `latest.delta_zero_prices` (0..N lines, see
					// four_leg_gamma_json), same as /4l/<asset>'s own. Gated by
					// the "Delta 0" checkbox.
					let deltaZeroPriceLines = [];
					// Gamma flip lines (violet, dotted) — one per entry in the
					// response's own `latest.gamma_flips` (prices where the
					// combined taker-signed portfolio gamma of the same
					// Expiry/Window trades, as of AS_OF_ISO, crosses zero —
					// see four_leg_gamma_json), same as /4l/<asset>'s own.
					// Gated by the "Gamma Flip" checkbox.
					let gammaFlipPriceLines = [];
					function clearGammaFlipLines() {
						gammaFlipPriceLines.forEach(l => series.removePriceLine(l));
						gammaFlipPriceLines = [];
					}
					// Gamma Peak lines (magenta, dashed) — the up-to-2 strongest
					// peaks/bottoms of that same combined taker-signed gamma
					// curve, as of AS_OF_ISO (`latest.gamma_peaks`, each
					// {price, value, leg} — see four_leg_gamma_json), same as
					// /4l/<asset>'s own. Gated by the "Gamma Peak" checkbox.
					let gammaPeakPriceLines = [];
					function clearGammaPeakLines() {
						gammaPeakPriceLines.forEach(l => series.removePriceLine(l));
						gammaPeakPriceLines = [];
					}
					function clearDeltaZeroLines() {
						deltaZeroPriceLines.forEach(l => series.removePriceLine(l));
						deltaZeroPriceLines = [];
						showDeltaSignBox(null);
					}
					// When the combined delta never crosses zero (as of
					// AS_OF_ISO) there's no Δ0 line to draw — the small
					// #delta-sign-box states which side of zero it stays on
					// instead (`latest.delta_zero_sign`: "positive"/"negative"/
					// "zero", null whenever a crossing exists). null hides it.
					// Ported from /4l/<asset> per product decision (2026-09-23).
					function showDeltaSignBox(sign) {
						const box = document.getElementById('delta-sign-box');
						if (!sign) { box.style.display = 'none'; return; }
						const text = { positive: 'Δ > 0 everywhere (no Δ0)', negative: 'Δ < 0 everywhere (no Δ0)', zero: 'Δ = 0 everywhere' };
						const color = { positive: '#2e7d32', negative: '#c62828', zero: '#555' };
						box.textContent = text[sign] || ('Δ ' + sign);
						box.style.color = color[sign] || '#555';
						box.style.display = 'block';
					}

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function tradeCountSuffix() {
						return tradeCount !== null ? '  ·  ' + tradeCount + ' trades' : '';
					}

					// WINDOW_HOURS is the string 'all' when the "All" option is
					// selected (no trailing-hours trade filter), the string
					// 'auto' when the "Auto (Time to Expiry)" option is selected
					// (server picks the window, see autoResolvedHours above), or
					// a number otherwise. A value that's a whole multiple of 24
					// displays in days rather than hours (matters mainly for
					// "Auto", which can resolve to a multi-day span for a
					// far-dated expiry — the dropdown itself now only offers
					// 1h..8h/12h/16h/24h/All); everything else stays hour-labeled.
					function hoursLabel(hours) {
						if (hours >= 24 && hours % 24 === 0) return (hours / 24) + 'd';
						return hours + 'h';
					}
					function windowLabel() {
						if (WINDOW_HOURS === 'all') return 'all trades';
						if (WINDOW_HOURS === 'auto') {
							return autoResolvedHours !== null
								? 'Auto → ' + hoursLabel(autoResolvedHours) + ' trailing window'
								: 'Auto trailing window';
						}
						return hoursLabel(WINDOW_HOURS) + ' trailing window';
					}

					function statusText() {
						// The picker is Berlin wall-clock — show that, plus the
						// UTC instant it resolved to (what actually filters
						// trades) in parentheses, so both are visible at a glance.
						const berlin = document.getElementById('as-of-input').value || '?';
						const utc = AS_OF_ISO ? AS_OF_ISO + 'Z' : '?';
						return ASSET + ' · TM · ' + (SELECTED_INSTRUMENT || '?')
							+ ' (' + windowLabel() + ')'
							+ '  ·  As of ' + berlin + ' Berlin (' + utc + ')'
							+ tradeCountSuffix();
					}

					function showSpinner() { document.getElementById('spinner').style.display = 'block'; }
					function hideSpinner() { document.getElementById('spinner').style.display = 'none'; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					let realCandles = [];

					// Same per-timeframe visible-window convention /4l/<asset>'s
					// own TF_WINDOW uses.
					const TF_WINDOW = { '15m': 5, '1h': 30, '4h': 15, '1d': 365 };
					const INTERVAL_SECONDS = { '15m': 15 * 60, '1h': 3600, '4h': 4 * 3600, '1d': 86400 };
					const FUTURE_MARGIN_DAYS = 5;

					function applyVisibleRange() {
						if (!realCandles.length) return;
						const days = TF_WINDOW[INTERVAL] || 15;
						const futureEdge = realCandles[realCandles.length - 1].time + FUTURE_MARGIN_DAYS * 86400;
						chart.timeScale().setVisibleRange({ from: futureEdge - days * 86400, to: futureEdge });
					}

					function rebuildSeriesData() {
						series.setData(realCandles);

						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureAxisSeries.setData(futureTicks);
						updateWindowVLine();
					}

					// Snaps an arbitrary instant to the nearest loaded candle
					// at-or-before it — same binary-search technique
					// /4l/<asset> uses (timeToCoordinate() only resolves a
					// coordinate for a time that exactly matches an existing
					// data/whitespace point on the shared time axis, it does
					// NOT interpolate an isolated point in between — see
					// updateWindowVLine() below).
					function nearestCandleTimeAtOrBefore(t) {
						if (!realCandles.length) return null;
						let lo = 0, hi = realCandles.length - 1, ans = -1;
						while (lo <= hi) {
							const mid = (lo + hi) >> 1;
							if (realCandles[mid].time <= t) { ans = mid; lo = mid + 1; }
							else hi = mid - 1;
						}
						return ans === -1 ? realCandles[0].time : realCandles[ans].time;
					}

					// "Window Line" checkbox (right after "Theme", checked by
					// default) — a plain client-side show/hide flag for the
					// single Window vertical line + label; no effect on the
					// Window dropdown or any fetch.
					let VLINE_SHOWN = true;
					function onToggleVLine() {
						VLINE_SHOWN = document.getElementById('vline-toggle').checked;
						updateWindowVLine();
					}

					// "Gamma Legs" checkbox (right after "Window Line",
					// UNCHECKED by default, matching /4l) — plain client-side
					// show/hide flag for the 4 gamma-leg lines (LC/LP/SC/SP)
					// only; the Dominant Leg line has its own checkbox.
					// Unchecking removes the 4 lines immediately
					// without a fetch; checking re-fetches via
					// refreshFourLegGamma() since `latest` isn't cached. Ported
					// from /4l/<asset> per product decision (2026-09-07).
					let SHOW_GAMMA_LEGS = false;
					function onToggleGammaLegs() {
						SHOW_GAMMA_LEGS = document.getElementById('gamma-legs-toggle').checked;
						if (!SHOW_GAMMA_LEGS) {
							if (bcgPriceLine) { series.removePriceLine(bcgPriceLine); bcgPriceLine = null; }
							if (bpgPriceLine) { series.removePriceLine(bpgPriceLine); bpgPriceLine = null; }
							if (scgPriceLine) { series.removePriceLine(scgPriceLine); scgPriceLine = null; }
							if (spgPriceLine) { series.removePriceLine(spgPriceLine); spgPriceLine = null; }
						} else {
							refreshFourLegGamma();
						}
					}

					// "Dominant Leg" checkbox (right after "Gamma Legs",
					// unchecked by default) — same plain client-side toggle
					// pattern. Ported from /4l/<asset> per product decision
					// (2026-09-23), replacing this page's former AVG checkbox.
					let SHOW_DOMINANT_LEG = false;
					function onToggleDominantLeg() {
						SHOW_DOMINANT_LEG = document.getElementById('dominant-leg-toggle').checked;
						if (!SHOW_DOMINANT_LEG) {
							if (dominantLegPriceLine) { series.removePriceLine(dominantLegPriceLine); dominantLegPriceLine = null; }
						} else {
							refreshFourLegGamma();
						}
					}

					// "Delta 0" checkbox (right after "Dominant Leg", unchecked by
					// default) — plain client-side show/hide flag for the Δ0
					// lines. Unchecking clears them without a fetch; checking
					// re-fetches via refreshFourLegGamma(). Ported from
					// /4l/<asset> per product decision (2026-09-23).
					// "Gamma Flip" checkbox (right after "Delta 0", unchecked by
					// default) — same plain client-side toggle pattern. Ported
					// from /4l/<asset> per product decision (2026-09-23).
					let SHOW_GAMMA_FLIP = false;
					function onToggleGammaFlip() {
						SHOW_GAMMA_FLIP = document.getElementById('gamma-flip-toggle').checked;
						if (!SHOW_GAMMA_FLIP) {
							clearGammaFlipLines();
						} else {
							refreshFourLegGamma();
						}
					}

					// "Gamma Peak" checkbox (right after "Gamma Flip", checked
					// by default) — same plain client-side toggle pattern.
					// Ported from /4l/<asset> per product decision (2026-09-29).
					let SHOW_GAMMA_PEAK = true;
					function onToggleGammaPeak() {
						SHOW_GAMMA_PEAK = document.getElementById('gamma-peak-toggle').checked;
						if (!SHOW_GAMMA_PEAK) {
							clearGammaPeakLines();
						} else {
							refreshFourLegGamma();
						}
					}

					let SHOW_DELTA_ZERO = false;
					function onToggleDeltaZero() {
						SHOW_DELTA_ZERO = document.getElementById('delta-zero-toggle').checked;
						if (!SHOW_DELTA_ZERO) {
							clearDeltaZeroLines();
						} else {
							refreshFourLegGamma();
						}
					}

					// Resolves the current Window selection to a plain hours
					// count for the vertical reference line, or null when no
					// line should be drawn: "All" has no start edge to mark,
					// and "Auto" has none until the server has resolved it
					// (autoResolvedHours).
					function effectiveWindowHours() {
						if (WINDOW_HOURS === 'all') return null;
						if (WINDOW_HOURS === 'auto') return autoResolvedHours;
						return WINDOW_HOURS;
					}

					// Positions the single Window reference line (and its
					// label) at the candle effectiveWindowHours() hours before
					// AS_OF_ISO — the start of the currently selected trailing
					// Window, relative to the inspected moment rather than real
					// "now" (per this page's "testing the past" design;
					// asOfEpochSeconds() instead of Date.now(), the one
					// difference from /4l's own updateWindowVLine()). An As-Of
					// moment is frozen, so unlike /4l this line never needs to
					// keep creeping forward on a timer once positioned (no
					// setInterval on this page at all). Hidden when the "Window
					// Line" checkbox is off, when Window is "All"/unresolved
					// "Auto", when AS_OF_ISO isn't set yet, or when the target
					// instant falls outside the visible range.
					function updateWindowVLine() {
						const vline = document.getElementById('window-vline');
						const label = document.getElementById('window-vline-label');
						if (!vline) return;
						const hrs = effectiveWindowHours();
						const asOfEpoch = asOfEpochSeconds();
						const hideAll = () => {
							vline.style.display = 'none';
							if (label) label.style.display = 'none';
						};
						if (!VLINE_SHOWN || hrs === null || hrs === undefined || asOfEpoch === null) { hideAll(); return; }
						const t = asOfEpoch - hrs * 3600 + tzOffset;
						const snapped = nearestCandleTimeAtOrBefore(t);
						const x = snapped === null ? null : chart.timeScale().timeToCoordinate(snapped);
						if (x === null || x === undefined) { hideAll(); return; }
						const rect = chartContainerEl.getBoundingClientRect();
						const left = Math.round(rect.left + x);
						vline.style.left = left + 'px';
						vline.style.display = 'block';
						if (label) {
							const sel = document.getElementById('window-select');
							label.textContent = (WINDOW_HOURS === 'auto' && autoResolvedHours !== null)
								? hoursLabel(autoResolvedHours)
								: (sel && sel.selectedOptions[0] ? sel.selectedOptions[0].textContent : hoursLabel(hrs));
							label.style.left = left + 'px';
							label.style.display = 'block';
						}
					}

					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					// `preserveView` (used by reloadForAsOf() below) keeps
					// whatever pan/zoom the user already set instead of
					// snapping back to the default TF_WINDOW range — without
					// this, nudging the "As Of" picker by even 1 hour used to
					// discard a manually-adjusted view every time, since this
					// function used to call applyVisibleRange() unconditionally
					// on every reload. The saved range is real epoch
					// timestamps (not bar indices), so it stays valid even
					// though the newly-fetched 500 candles shift by however
					// many bars the As-Of change moved.
					async function loadCandles(preserveView) {
						const savedRange = preserveView ? chart.timeScale().getVisibleRange() : null;
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						if (savedRange) {
							chart.timeScale().setVisibleRange(savedRange);
						} else {
							applyVisibleRange();
						}
						// rebuildSeriesData() already calls updateWindowVLine() once,
						// but that happens BEFORE the visible range above is
						// (re)established — recompute here too so the line
						// reflects the actual window immediately.
						updateWindowVLine();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
						setStatus(statusText());
					}

					async function setExpiry(instr) {
						SELECTED_INSTRUMENT = instr;
						await refreshFourLegGamma();
					}

					// Populates the "Expiry" dropdown from every instrument
					// that had already traded and hadn't yet expired AS OF
					// AS_OF_ISO (/api/expiries/<asset>?as_of=<AS_OF_ISO> ->
					// dankbit.bands._distinct_expirations_asof()). Called from
					// init() and again from reloadForAsOf() on every As-Of
					// change, since the active-expiry set itself moves with the
					// inspected moment. Preserves the current selection when it
					// still exists in the new list, else falls back to the
					// nearest (first, soonest) entry.
					async function loadExpiries() {
						const select = document.getElementById('expiry-select');
						if (!select) return;
						const data = await (await fetch('/api/expiries/' + ASSET + '?as_of=' + encodeURIComponent(AS_OF_ISO))).json();
						const expiries = data.expiries || [];
						const prev = SELECTED_INSTRUMENT;
						select.innerHTML = '';
						expiries.forEach(instr => {
							const opt = document.createElement('option');
							opt.value = instr;
							opt.textContent = instr;
							select.appendChild(opt);
						});
						SELECTED_INSTRUMENT = (prev && expiries.indexOf(prev) !== -1)
							? prev
							: (expiries.length ? expiries[0] : null);
						if (SELECTED_INSTRUMENT) select.value = SELECTED_INSTRUMENT;
						// The Expiry select's own width can change once real
						// instrument strings replace its initial empty state,
						// which can shift how #tf-bar wraps.
						repositionBelowToolbar();
					}

					async function setWindow(hours) {
						WINDOW_HOURS = (hours === 'all' || hours === 'auto') ? hours : parseInt(hours, 10);
						autoResolvedHours = null;
						updateWindowVLine();
						await refreshFourLegGamma();
						setStatus(statusText());
					}

					// Rounds and abbreviates large raw dollar-gamma values
					// (hundreds of millions to billions is typical here) —
					// thousands as K, millions as M, sign preserved (long
					// legs' gamma is positive, short legs' is negative, per
					// this addon's own convention — see per_leg_greeks).
					function formatAbbreviated(value) {
						const sign = value < 0 ? '-' : '';
						const abs = Math.abs(value);
						if (abs >= 1e6) return sign + Math.round(abs / 1e6).toLocaleString('en-US') + 'M';
						if (abs >= 1e3) return sign + Math.round(abs / 1e3).toLocaleString('en-US') + 'K';
						return sign + Math.round(abs).toLocaleString('en-US');
					}

					// Fetches and redraws the 4 gamma-leg lines (+ Dominant Leg,
					// Δ0, γ flip) for the current Expiry/Window as of AS_OF_ISO —
					// same shape as /4l/<asset>'s own refreshFourLegGamma(), minus
					// the periodic re-poll (this only ever runs in direct
					// response to a control change on this page).
					async function refreshFourLegGamma() {
						showSpinner();
						try {
							const data = await (await fetch(fourLegGammaUrl())).json();
							const points = data.points || [];
							const latest = points.length ? points[points.length - 1] : null;

							// Server-resolved window in hours (always present,
							// even with zero points) — only meaningful for
							// display while WINDOW_HOURS === 'auto', see
							// windowLabel()/hoursLabel() above.
							autoResolvedHours = typeof data.window_hours === 'number' ? data.window_hours : null;
							// "Auto" only knows its real trailing-hours span once
							// the server resolves it — reposition the line now.
							updateWindowVLine();

							// 0 (not null) once resolved with no trades at all in
							// the current Window/Expiry — null only ever means
							// "haven't fetched yet", so tradeCountSuffix() can
							// tell "0 trades" apart from "not loaded".
							tradeCount = latest ? latest.trade_count : 0;
							setStatus(statusText());

							if (bcgPriceLine) { series.removePriceLine(bcgPriceLine); bcgPriceLine = null; }
							if (bpgPriceLine) { series.removePriceLine(bpgPriceLine); bpgPriceLine = null; }
							if (scgPriceLine) { series.removePriceLine(scgPriceLine); scgPriceLine = null; }
							if (spgPriceLine) { series.removePriceLine(spgPriceLine); spgPriceLine = null; }
							if (dominantLegPriceLine) { series.removePriceLine(dominantLegPriceLine); dominantLegPriceLine = null; }
							clearDeltaZeroLines();
							clearGammaFlipLines();
							clearGammaPeakLines();
							if (!latest) {
								return;
							}

							// Delta = 0 — every price where the combined
							// portfolio delta of this Expiry/Window's trades
							// (as of AS_OF_ISO) crosses zero.
							if (SHOW_DELTA_ZERO) {
								const dzColor = chartColors.deltazero;
								(latest.delta_zero_prices || []).forEach(price => {
									deltaZeroPriceLines.push(series.createPriceLine({
										price: price, color: dzColor, lineWidth: 2,
										lineStyle: LightweightCharts.LineStyle.Dotted,
										axisLabelVisible: true, axisLabelColor: dzColor,
										title: 'Δ0',
									}));
								});
								showDeltaSignBox(latest.delta_zero_sign);
							}

							// Gamma flip — label says which side is positive/
							// negative gamma, e.g. "γ flip (taker): − below / + above"
							// (each entry's own `below`/`above` sign).
							if (SHOW_GAMMA_FLIP) {
								const gfColor = chartColors.gammaflip;
								const sym = sign => sign === 'positive' ? '+' : '−';
								(latest.gamma_flips || []).forEach(flip => {
									gammaFlipPriceLines.push(series.createPriceLine({
										price: flip.price, color: gfColor, lineWidth: 2,
										lineStyle: LightweightCharts.LineStyle.Dotted,
										axisLabelVisible: true, axisLabelColor: gfColor,
										title: 'γ flip (taker): ' + sym(flip.below) + ' below / ' + sym(flip.above) + ' above',
									}));
								});
							}

							// Gamma Peaks — up to 2 strongest extrema of the same
							// combined gamma curve, each labeled with the leg
							// driving it, e.g. "γ peak LC | 471M".
							if (SHOW_GAMMA_PEAK) {
								const gpColor = chartColors.gammapeak;
								(latest.gamma_peaks || []).forEach(pk => {
									gammaPeakPriceLines.push(series.createPriceLine({
										price: pk.price, color: gpColor, lineWidth: 2,
										lineStyle: LightweightCharts.LineStyle.Dashed,
										axisLabelVisible: true, axisLabelColor: gpColor,
										title: 'γ peak ' + pk.leg + ' | ' + formatAbbreviated(pk.value),
									}));
								});
							}

							// 0.0 means absent (same convention every gamma_band/
							// smart_liq_*_price field in this addon uses) — no
							// line drawn rather than a spurious price-0 line.
							// axisLabelColor matches each line's own color here
							// so the label is identifiable by color at a glance
							// with 4 lines on one chart. Colors come from
							// chartColors (user-configurable via the "Settings"
							// button/dankbit_tm_chart_colors). Also gated on the
							// "Gamma Legs" checkbox (SHOW_GAMMA_LEGS) — the
							// Dominant Leg line has its own checkbox.
							if (SHOW_GAMMA_LEGS && latest.bcg_price) {
								bcgPriceLine = series.createPriceLine({
									price: latest.bcg_price, color: chartColors.bcg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bcg,
									title: 'LC ' + formatAbbreviated(latest.bcg_value),
								});
							}
							if (SHOW_GAMMA_LEGS && latest.bpg_price) {
								bpgPriceLine = series.createPriceLine({
									price: latest.bpg_price, color: chartColors.bpg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.bpg,
									title: 'LP ' + formatAbbreviated(latest.bpg_value),
								});
							}
							if (SHOW_GAMMA_LEGS && latest.scg_price) {
								scgPriceLine = series.createPriceLine({
									price: latest.scg_price, color: chartColors.scg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.scg,
									title: 'SC ' + formatAbbreviated(latest.scg_value),
								});
							}
							if (SHOW_GAMMA_LEGS && latest.spg_price) {
								spgPriceLine = series.createPriceLine({
									price: latest.spg_price, color: chartColors.spg, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: chartColors.spg,
									title: 'SP ' + formatAbbreviated(latest.spg_value),
								});
							}
							// Dominant Leg — the present leg (price != 0) with the
							// largest |gamma value| in this Expiry/Window/As-Of;
							// the line sits at that leg's own gamma price. Label
							// e.g. "DOM LC | 71M". Skipped when no leg is present.
							if (SHOW_DOMINANT_LEG) {
								const legs = [
									{ name: 'LC', price: latest.bcg_price, value: latest.bcg_value },
									{ name: 'LP', price: latest.bpg_price, value: latest.bpg_value },
									{ name: 'SC', price: latest.scg_price, value: latest.scg_value },
									{ name: 'SP', price: latest.spg_price, value: latest.spg_value },
								].filter(leg => leg.price);
								if (legs.length) {
									const dom = legs.reduce((a, b) => Math.abs(b.value) > Math.abs(a.value) ? b : a);
									const domColor = chartColors.dominant;
									dominantLegPriceLine = series.createPriceLine({
										price: dom.price, color: domColor, lineWidth: 2,
										lineStyle: LightweightCharts.LineStyle.Solid,
										axisLabelVisible: true, axisLabelColor: domColor,
										title: 'DOM ' + dom.name + ' | ' + formatAbbreviated(dom.value),
									});
								}
							}
						} finally {
							hideSpinner();
						}
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					function openSettingsModal() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						document.getElementById('settings-modal').style.display = 'flex';
					}

					function closeSettingsModal() {
						document.getElementById('settings-modal').style.display = 'none';
					}

					function saveChartColors() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) chartColors[key] = input.value;
						});
						localStorage.setItem(COLOR_STORAGE_KEY, JSON.stringify(chartColors));
						refreshFourLegGamma();
						closeSettingsModal();
					}

					function resetChartColors() {
						chartColors = Object.assign({}, DEFAULT_COLORS);
						localStorage.removeItem(COLOR_STORAGE_KEY);
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						refreshFourLegGamma();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					// Re-runs every As-Of-dependent fetch on this page against
					// the current AS_OF_ISO — called whenever the "As Of" input
					// changes or the "Now" button is pressed. Candles, the
					// Expiry list, and the 4 gamma legs all depend on
					// AS_OF_ISO, so all three are re-fetched together (unlike
					// setTf/setExpiry/setWindow, which each only touch the one
					// thing they control). loadCandles(true) preserves the
					// user's own pan/zoom instead of resetting it — see
					// loadCandles() above.
					async function reloadForAsOf() {
						showSpinner();
						try {
							await loadCandles(true);
							await loadExpiries();
							await refreshFourLegGamma();
							setStatus(statusText());
						} catch (e) {
							setStatus('Error: ' + e.message);
						} finally {
							hideSpinner();
						}
					}

					function onAsOfChange() {
						const value = document.getElementById('as-of-input').value;
						if (!value) return;
						setAsOfInput(value);
						reloadForAsOf();
					}

					// Jumps the picker to the current Berlin date and hour
					// (minutes zeroed, via toDatetimeLocalBerlin()).
					function jumpToNow() {
						setAsOfInput(toDatetimeLocalBerlin(new Date()));
						reloadForAsOf();
					}

					async function init() {
						try {
							setAsOfInput(INITIAL_AS_OF || defaultAsOfBerlinNaive());
							await loadCandles();
							await loadExpiries();
							await refreshFourLegGamma();
							setStatus(statusText());
						}
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
					// No setInterval calls at all on this page — an As-Of
					// moment is frozen by definition, so unlike /4l/<asset>
					// (candle poll, gamma-leg poll, and a 5s vline-advance
					// tick) there's nothing here that needs to keep moving
					// forward in real time once AS_OF_ISO stops changing.
				//
